cat > /etc/nftables.conf <<'NFT_EOF'
#!/usr/sbin/nft -f
flush ruleset

define cluster_v4 = { 10.100.236.10, 10.100.236.11, 10.100.236.12 }

table inet filter {
    chain input {
        type filter hook input priority filter; policy drop;

        iifname "lo" accept
        ct state established,related accept

        ip protocol icmp accept
        ip6 nexthdr icmpv6 accept
        udp sport 67 udp dport 68 accept
        udp sport 547 udp dport 546 accept

        tcp dport 22 accept

        ip saddr $cluster_v4 tcp dport { 3306, 4444, 4567, 4568 } accept
        ip saddr $cluster_v4 udp dport 4567 accept
    }

    chain forward {
        type filter hook forward priority filter; policy drop;
    }

    chain output {
        type filter hook output priority filter; policy accept;
    }
}
NFT_EOF
chown root:root /etc/nftables.conf
chmod 0644 /etc/nftables.conf
nft -c -f /etc/nftables.conf
nft -f /etc/nftables.conf
systemctl enable nftables
systemctl restart nftables
systemctl is-active nftables

